#include <stdlib.h>
#include <string.h>

void allocateAndFill(int buffer_size) {
    char *buffer = malloc(buffer_size); // Allocate the buffer on the heap instead of the stack

    if (buffer == NULL) {
        exit(EXIT_FAILURE);  // Check for allocation error
    }

