['Here's an example in C that performs these tasks. Please modify the filenames as required:

```C
#include <stdio.h>
#include <stdlib.h>

int main() {
    FILE *input_file, *output_file;
    char buffer[1024];
    int checksum = 0, bytes_read = 0;

    // Open the file for reading
    input_file = fopen("input.txt", "r");
    if (input_file == NULL) {
        printf("Could not open file\n");
        return -1;
    }

    // Read and calculate checksum
    while ((bytes_read = fread(buffer, 1, sizeof buffer, input_file)) > 0) {
        for (int i = 0; i < bytes_read; ++i) {
            checksum += buffer[i];
        }
    }

    // Close the file
    fclose(input_file);

    if (checksum == 0) {
        printf("The file is empty\n");
        return -1;
    }

    // Open a file for writing
    output_file = fopen("output.txt", "w");
    if (output_file == NULL) {
        printf("Could not open file for writing\n");
        return -1;
    }

    // Write bytes read and checksum to a file
    fprintf(output_file, "Bytes read: %d\n", bytes_read);
    fprintf(output_file, "Checksum: %d\n", checksum);

    // Close the file
    fclose(output_file);

    return 0;
}
```
This code assumes that you have two files called `input.txt` and `output.txt` in the same directory as your source file. Make sure to replace these names with the actual filenames you are using.
