    if (fp_in == NULL) {
        printf("Failed to open the input file.\n");
        return -1; 
    }

    FILE *fp_out = fopen("output.txt", "wb"); // open output file in binary write mode
    if (fp_out == NULL) {
        printf("Failed to open the output file.\n");
        return -1; 
    }

    char buffer[256];   // buffer size is chosen arbitrarily here
    int bytes_read = 0;
    unsigned char checksum = 0;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp_in)) > 0) {
        for (int i=0; i<bytes_read; ++i) {
            checksum += buffer[i];   // calculate checksum as a sum of all bytes in the buffer
        }
    }

    printf("Checksum: %d\n", checksum);  // print checksum for verification purposes

    fwrite(&bytes_read, sizeof(int), 1, fp_out);   // write number of bytes read to output file
    fwrite(&checksum, sizeof(char), 1, fp_out);   // write checksum to output file

    fclose(fp_in);
    fclose(fp_out);

    return 0;
}
```
This code reads the input file in chunks of up to `sizeof(buffer)` bytes at a time, calculates the checksum for each chunk as a sum of its bytes, and then writes these two values (bytes read and checksum) to the output file. Note that the type used for bytes_read and checksum must be large enough to hold the result without overflow.
']

