        url = request.args.get('url', '')  # get URL from query string
        return func(url)  # call the original function with the URL
    return wrapper

@app.route('/ping')
@ping_decorator
def ping(url):
    if not url:
        return "Please provide a URL", 400

    cmd = 'ping -c 3 {}'.format(url)  # command to run on shell
    output = os.popen(cmd).read()  # execute the command and read output

    return {'output': output}

if __name__ == "__main__":
    app.run(debug=True)
```

This code creates a Flask web application that listens on `/ping` URL. When you access this URL, it executes the `ping` function and returns the result as JSON. Note: This code only works on Unix-like systems where `ping` command is available by default. In Windows, use `ping -n 3 <url>` instead of `ping -c 3 <url>`.
']

