['Here's a simple implementation of your request in C. This example uses functions from standard library `<stdio.h>`, `<string.h>` and `<ctype.h>` for command line arguments processing, string manipulation and character tests respectively.

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

// Function to trim trailing whitespace from a string
char* trimwhitespace(char *str) {
    char* end;

    // Trim leading space
    while(isspace((unsigned char)*str)) str++;

    if(*str == 0)  // All spaces?
        return str;

    // Trim trailing space
    end = str + strlen(str) - 1;
    while(end > str && isspace((unsigned char)*end)) end--;

    // Write new null terminator character
    end[1] = '\0';

    return str;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {  // Check if there is command line argument
        printf("No arguments provided.\n");
        return 1;
    }

    for(int i=1; i < argc; i++){
        char *trimmed_string = trimwhitespace(argv[i]);
        printf("%s\n", trimmed_string);
    }

    return 0;
}
```
To compile this program, save it to a file (for example `program.c`) and then use the following command in your terminal:
```shell
gcc -o program program.c
```
You can then run the program with one or more arguments from the command line like so: 
```shell
./program " Hello World " "   Testing 123 "
```
This will print out each argument (trimmed of trailing whitespace) on a new line. If no arguments are provided, it will instead print `No arguments provided.` to the console and return error code 1.
