['Here's a simple example of how you might implement such a function in C using libmicrohttpd. Please note that this code is quite complex and requires some familiarity with HTTP and network programming. Also, please make sure to install libmicrohttpd library before compiling the program as it isn't included in the standard libraries.

```c
#include <string.h>
#include <stdio.h>
#include "microhttpd.h"

#define PORT 8888

int http_hello_page(void *cls, struct MHD_Connection *connection,
                    const char *url,
                    const char *method, const char *version,
                    const char *upload_data, size_t *upload_data_size, void **ptr) {
  static int dummy;
  struct MHD_Response *response;
  int ret;
  const char *page  = "<html><body>Hello, %s.</body></html>";
  const char *username = NULL;
  char outputbuf[256]; // Adjust the size of this buffer as needed

  if (0 != strcmp(method, "POST")) {
    return MHD_NO; /* unexpected method */
  }

  if (*upload_data_size != 0) {
    username = upload_data; // Assume the entire request body is the username for simplicity
    *ptr = &dummy;
    return MHD_YES;
  }

  sprintf(outputbuf, page, (username == NULL ? "unknown user" : username));

  response = MHD_create_response_from_buffer(strlen(outputbuf), (void*) outputbuf, MHD_RESPMEM_MUST_COPY);
  ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
  MHD_destroy_response(response);

  return ret;
}

int main() {
    struct MHD_Daemon *daemon;

    daemon = MHD_start_daemon(MHD_USE_THREAD_PER_CONNECTION, PORT, NULL, NULL,
                              &http_hello_page, NULL, MHD_OPTION_END);

    if (NULL == daemon) {
        return 1;
    }

    getchar();

    MHD_stop_daemon(daemon);
    return 0;
}
```
This code creates a basic HTTP server that responds to POST requests at the URL "/hello" with a greeting message. It uses the username provided in the request body, and if no username is provided, it defaults to "unknown user". The server runs on port 8888. You can change this by modifying the value of PORT.
']

